const require = createRequire(import.meta.url);
const brandIconDirectory = path.join(path.dirname(require.resolve('@lobehub/icons-static-svg/package.json')), 'icons');
const brandIcons = {
  codex: readFileSync(path.join(brandIconDirectory, 'codex.svg'), 'utf8'),
  claude: readFileSync(path.join(brandIconDirectory, 'claude.svg'), 'utf8'),
};

