function renderTree(){let h='<div class="tree-item '+(S.selected.kind==='project'?'active':'')+'" data-select="project"><span class="tree-icon">'+uiIcon('project')+'</span><div><div class="tree-label">'+esc(S.project.title)+'</div><div class="tree-sub">'+S.project.width+'×'+S.project.height+' · '+S.project.fps+' fps</div></div></div>';S.project.scenes.forEach(scene=>{h+='<div class="tree-item '+(S.selected.kind==='scene'&&S.selected.id===scene.id?'active':'')+'" data-select="scene" data-id="'+esc(scene.id)+'"><span class="tree-icon">'+uiIcon('scene')+'</span><div><div class="tree-label">'+esc(scene.id)+'</div><div class="tree-sub">'+esc(scene.purpose)+'</div></div></div>';scene.layers.forEach(layer=>{h+='<div style="padding-left:18px" class="tree-item '+(S.selected.kind==='layer'&&S.selected.id===layer.id?'active':'')+'" data-select="layer" data-id="'+esc(layer.id)+'" data-scene="'+esc(scene.id)+'"><span class="tree-icon">'+icon(layer.type)+'</span><div class="tree-label">'+esc(layer.id)+'</div></div>'})});$('#sceneTree').innerHTML=h;$$('[data-select]').forEach(e=>{e.onclick=()=>select(e.dataset.select,e.dataset.id,{sceneId:e.dataset.scene});if(e.dataset.select==='layer')e.ondblclick=()=>editLayer(e.dataset.scene,e.dataset.id)})}
function renderMotionList(){const q=$('#motionSearch').value.toLowerCase();const list=S.catalog.motions.filter(m=>(m.id+' '+m.title+' '+m.roles.join(' ')+' '+m.signature+' '+(m.libraryTitle||'')).toLowerCase().includes(q)).slice(0,10);$('#motionList').innerHTML=list.map(m=>'<div class="catalog-item" data-motion="'+esc(m.id)+'"><span class="tree-icon">'+uiIcon('motion')+'</span><div><strong>'+esc(m.title)+'</strong><small>'+esc(m.signature)+'</small>'+(m.source==='custom'?'<span class="badge" style="display:inline-block;margin:7px 0 0">'+esc(m.libraryTitle)+'</span>':'')+'</div></div>').join('');$$('[data-motion]').forEach(e=>e.onclick=()=>applyMotion(e.dataset.motion))}
function motionLibraryExample(){return JSON.stringify({schemaVersion:1,id:'brand-motion',title:'Brand Motion',version:'1.0.0',motions:[{id:'soft-rise',title:'Soft rise',roles:['entrance'],energy:['balanced'],signature:'A clean vertical entrance.',duration:[0.3,0.8],cost:1,accessibility:['Respect reduced motion'],tracks:{y:[{at:0,value:36,scaleWithIntensity:true},{at:1,value:0,ease:'cubic-out'}],opacity:[{at:0,value:0},{at:.7,value:1,ease:'cubic-out'}]}}]},null,2)}
function showMotionLibraries(){const libraries=S.catalog.motionLibraries||[],rows=libraries.map(l=>'<div class="catalog-item"><span class="tree-icon">'+uiIcon('library')+'</span><div><strong>'+esc(l.title)+'</strong><small>'+esc(l.id)+' · v'+esc(l.version)+' · '+l.motions+' motion'+(l.motions===1?'':'s')+'</small></div></div>').join('');openModal('Motion libraries','<div class="tree-sub" style="margin-bottom:12px;line-height:1.5">Import declarative JSON motion recipes. Imports are stored with this project and run through the native renderer.</div>'+(rows||'<div class="empty">No custom libraries imported.</div>')+'<button class="primary icon-label" style="width:100%;margin-top:14px" id="importMotionLibrary">'+uiIcon('add')+'Import JSON library</button><details style="margin-top:14px"><summary class="ghost" style="display:flex;align-items:center;cursor:pointer">JSON format</summary><pre class="request-response" style="font-size:10px;max-height:240px;overflow:auto">'+esc(motionLibraryExample())+'</pre></details>');$('#importMotionLibrary').onclick=()=>$('#motionLibraryPicker').click()}
async function importMotionLibrary(file){if(!file)return;try{const raw=JSON.parse(await file.text()),result=await api('/api/motion-libraries',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(raw)});S.catalog.motions=result.catalog.motions;S.catalog.motionLibraries=result.catalog.motionLibraries;renderMotionList();showMotionLibraries();toast('Imported '+result.library.title,'good','motion-library:'+result.library.id)}catch(error){toast(error.message,'bad','motion-library-error')}finally{$('#motionLibraryPicker').value=''}}
