$('#snapToggle').onclick=()=>{S.snap=!S.snap;$('#snapToggle').classList.toggle('active',S.snap);toast('Snapping '+(S.snap?'on':'off'),'good','snap-state')};$('#timelineZoomOut').onclick=()=>{S.timelineZoom=Math.max(.5,S.timelineZoom-.25);renderTimeline()};$('#timelineZoomIn').onclick=()=>{S.timelineZoom=Math.min(4,S.timelineZoom+.25);renderTimeline()};$('#timeline').onscroll=e=>{$('#trackLabels').scrollTop=e.currentTarget.scrollTop};$('#timeline').onclick=e=>{if(e.target.closest('.clip,.phase-clip'))return;const rect=$('#tracks').getBoundingClientRect(),x=Math.max(0,Math.min(rect.width,e.clientX-rect.left));showFrame(x/rect.width*(frames()-1))};
$('#canvas').onpointerdown=e=>{if(e.target===$('#canvas')||e.target===$('#world')||e.target===$('#wires')){S.drag={type:'pan',startX:e.clientX,startY:e.clientY,x:S.pan.x,y:S.pan.y};$('#canvas').classList.add('panning');$('#canvas').setPointerCapture(e.pointerId)}};window.onpointermove=e=>{if(!S.drag)return;if(S.drag.type==='pan'){S.pan={x:S.drag.x+e.clientX-S.drag.startX,y:S.drag.y+e.clientY-S.drag.startY};applyWorldTransform()}else if(S.drag.type==='node'){const n=nodeById(S.drag.id);if(n){n.x=S.drag.x+(e.clientX-S.drag.startX)/S.zoom;n.y=S.drag.y+(e.clientY-S.drag.startY)/S.zoom;renderWorkflow()}}else if(S.drag.type==='phase')movePhase(e);else if(S.drag.type==='layer-time')moveLayer(e);else if(S.drag.type==='audio-time')moveAudio(e);else if(S.drag.type==='stage')moveStage(e)};window.onpointerup=e=>{const drag=S.drag;if(drag?.type==='node')saveStudio();if(['phase','layer-time','audio-time'].includes(drag?.type)&&drag.changed){showTimelineGuide();renderTimeline();renderInspector();saveProject()}if(drag?.type==='stage'&&drag.changed){showStageGuides();renderStageOverlay();renderInspector();saveProject()}if(drag?.type==='connect'){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.node');if(target&&target.dataset.node!==drag.from&&nodeById(target.dataset.node)){const exists=S.studio.edges.some(edge=>edge.from===drag.from&&edge.to===target.dataset.node);if(!exists){S.studio.edges.push({id:'edge:'+crypto.randomUUID(),from:drag.from,to:target.dataset.node,label:'informs'});saveStudio();renderWorkflow();toast('Workflow connection created')}}}S.drag=null;$('#canvas').classList.remove('panning')};$('#canvas').onwheel=e=>{e.preventDefault();const rect=$('#canvas').getBoundingClientRect(),mx=e.clientX-rect.left,my=e.clientY-rect.top,old=S.zoom,next=Math.max(.25,Math.min(1.8,old*Math.exp(-e.deltaY*.001)));S.pan.x=mx-(mx-S.pan.x)*next/old;S.pan.y=my-(my-S.pan.y)*next/old;S.zoom=next;applyWorldTransform()};window.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!e.shiftKey){e.preventDefault();undo()}if((e.ctrlKey||e.metaKey)&&(e.key==='y'||(e.shiftKey&&e.key==='z'))){e.preventDefault();redo()}};
window.addEventListener('pointermove',event=>{const drag=S.drag;if(drag?.type!=='node'||!drag.node||!drag.temporary)return;drag.node.x=drag.x+(event.clientX-drag.startX)/S.zoom;drag.node.y=drag.y+(event.clientY-drag.startY)/S.zoom;drag.moved=true;if(drag.element){drag.element.style.left=drag.node.x+'px';drag.element.style.top=drag.node.y+'px'}},true);
