function undo(){const raw=S.undo.pop();if(!raw)return;S.redo.push(JSON.stringify({project:S.project,studio:S.studio}));const v=JSON.parse(raw);S.project=v.project;S.studio=v.studio;saveStudio();saveProject();renderAll()}function redo(){const raw=S.redo.pop();if(!raw)return;S.undo.push(JSON.stringify({project:S.project,studio:S.studio}));const v=JSON.parse(raw);S.project=v.project;S.studio=v.studio;saveStudio();saveProject();renderAll()}
